def publishGitHubCommitStatus(String credentialsId, String commit, String state, String description) {
    if (!(commit ==~ /[0-9a-f]{40}/)) {
        error("Cannot publish a GitHub status for invalid commit SHA '${commit}'.")
    }
    if (!['pending', 'success', 'failure', 'error'].contains(state)) {
        error("Invalid GitHub commit-status state '${state}'.")
    }

    // Bind the token only for this trusted API request, never while a shell
    // command from the PR checkout is running.
    withCredentials([usernamePassword(
        credentialsId: credentialsId,
        usernameVariable: 'GITHUB_STATUS_USERNAME',
        passwordVariable: 'GITHUB_STATUS_TOKEN'
    )]) {
        withEnv([
            "GITHUB_STATUS_COMMIT=${commit}",
            "GITHUB_STATUS_STATE=${state}",
            "GITHUB_STATUS_DESCRIPTION=${description}"
        ]) {
            sh '''#!/bin/bash
                set -euo pipefail

                payload="$(printf '{"state":"%s","context":"continuous-integration/jenkins/perlmutter-gpu","description":"%s"}' "${GITHUB_STATUS_STATE}" "${GITHUB_STATUS_DESCRIPTION}")"
                curl --fail --silent --show-error \
                    --retry 2 --connect-timeout 15 --max-time 45 \
                    --request POST \
                    --header 'Accept: application/vnd.github+json' \
                    --header 'X-GitHub-Api-Version: 2022-11-28' \
                    --header "Authorization: Bearer ${GITHUB_STATUS_TOKEN}" \
                    --header 'Content-Type: application/json' \
                    --data "$payload" \
                    --output /dev/null --write-out 'GitHub Perlmutter status: %{http_code}\\n' \
                    "https://api.github.com/repos/gkeyllorg/gkeyll/statuses/${GITHUB_STATUS_COMMIT}"
            '''
        }
    }
}

def submitSlurmJob(String kind, String payload, String cpus, String timeLimit, List<String> extraExports = []) {
    def qos = requireValue('PERLMUTTER_SLURM_QOS', env.PERLMUTTER_SLURM_QOS)
    def account = env.PERLMUTTER_SLURM_ACCOUNT?.trim()
    def idFile = "slurm-${kind}-job-id.txt"
    def statusFile = "slurm-${kind}-job-status.txt"
    def outputFile = "slurm-${kind}-%j.out"
    def exports = [
        "CI_WORKSPACE=${env.WORKSPACE}",
        "CI_SLURM_JOB_KIND=${kind}",
        "CI_SLURM_JOB_ID_FILE=${idFile}",
        "CI_SLURM_JOB_STATUS_FILE=${statusFile}"
    ] + extraExports

    withEnv([
        "CI_WORKSPACE=${env.WORKSPACE}",
        "CI_SLURM_JOB_KIND=${kind}",
        "CI_SLURM_JOB_ID_FILE=${idFile}",
        "CI_SLURM_JOB_STATUS_FILE=${statusFile}",
        "CI_PERLMUTTER_QOS=${qos}",
        "CI_PERLMUTTER_TIME=${timeLimit}",
        "CI_PERLMUTTER_ACCOUNT=${account ?: ''}",
        "CI_PERLMUTTER_CPUS=${cpus}",
        "CI_SLURM_PAYLOAD=${payload}",
        "CI_SLURM_EXPORTS=${exports.join(',')}",
        "CI_SLURM_OUTPUT=${outputFile}"
    ]) {
        sh '''#!/bin/bash -l
            set -euo pipefail

            job_id=''

            write_status() {
                printf 'job_id=%s\nstate=%s\nexit_code=%s\nelapsed_seconds=%s\n' \
                    "$job_id" "$1" "${2:-}" "${3:-}" > "$CI_SLURM_JOB_STATUS_FILE"
            }

            cancel_submitted_job() {
                trap - INT TERM
                if [[ -z "$job_id" ]]; then
                    exit 143
                fi

                echo "Jenkins interrupted; cancelling Slurm job $job_id"
                scancel "$job_id" || true
                while :; do
                    state="$(squeue --noheader --jobs="$job_id" --format='%T' | head -n 1 || true)"
                    if [[ -z "$state" ]]; then
                        break
                    fi
                    echo "Waiting for Slurm job $job_id to stop (state: $state)"
                    sleep 5
                done
                write_status 'CANCELLED_BY_JENKINS'
                exit 143
            }

            trap cancel_submitted_job INT TERM

            sbatch_args=(
                --parsable
                "--job-name=gkyl-ci-${CI_SLURM_JOB_KIND}-${BUILD_NUMBER}"
                --nodes=1
                --ntasks=1
                "--cpus-per-task=${CI_PERLMUTTER_CPUS}"
                "--qos=${CI_PERLMUTTER_QOS}"
                "--time=${CI_PERLMUTTER_TIME}"
                "--output=${CI_WORKSPACE}/${CI_SLURM_OUTPUT}"
                "--chdir=${CI_WORKSPACE}"
                "--export=ALL,${CI_SLURM_EXPORTS}"
            )
            if [[ -n "${CI_PERLMUTTER_ACCOUNT:-}" ]]; then
                sbatch_args+=("--account=${CI_PERLMUTTER_ACCOUNT}")
            fi

            submission="$(sbatch "${sbatch_args[@]}" "$CI_SLURM_PAYLOAD")"
            job_id="${submission%%;*}"
            if [[ ! "$job_id" =~ ^[0-9]+(_[0-9]+)?$ ]]; then
                echo "ERROR: Could not parse Slurm job ID from: $submission" >&2
                exit 1
            fi
            printf '%s\n' "$job_id" > "$CI_SLURM_JOB_ID_FILE"
            echo "Submitted ${CI_SLURM_JOB_KIND} Slurm job $job_id"

            previous_state=''
            while :; do
                state="$(squeue --noheader --jobs="$job_id" --format='%T' | head -n 1 || true)"
                if [[ -z "$state" ]]; then
                    break
                fi
                if [[ "$state" != "$previous_state" ]]; then
                    echo "${CI_SLURM_JOB_KIND} Slurm job $job_id state: $state"
                    previous_state="$state"
                fi
                sleep 5
            done

            # Slurm accounting can lag briefly after a job disappears from
            # squeue. Query the allocation record only (-X) until it appears.
            record=''
            for attempt in {1..6}; do
                record="$(sacct --noheader --parsable2 --allocations --jobs="$job_id" \
                    --format=State,ExitCode,ElapsedRaw | head -n 1 || true)"
                if [[ -n "$record" ]]; then
                    break
                fi
                echo "Waiting for Slurm accounting record for job $job_id ($attempt/6)"
                sleep 5
            done
            if [[ -z "$record" ]]; then
                write_status 'UNKNOWN'
                echo "ERROR: No Slurm accounting record found for job $job_id" >&2
                exit 1
            fi

            IFS='|' read -r final_state exit_code elapsed_seconds <<< "$record"
            write_status "$final_state" "$exit_code" "$elapsed_seconds"
            echo "${CI_SLURM_JOB_KIND} Slurm job $job_id finished: state=$final_state exit_code=$exit_code elapsed_seconds=$elapsed_seconds"
            if [[ "$final_state" == COMPLETED* && "$exit_code" == '0:0' ]]; then
                exit 0
            fi
            exit 1
        '''
    }
}

def submitUnitTests() {
    submitSlurmJob(
        'unit',
        'ci/jenkins/slurm-unit-tests.perlmutter-gpu.sh',
        '4',
        (env.PERLMUTTER_SLURM_TIME ?: '00:30:00').trim()
    )
}

def submitRegressionTests() {
    def jobs = regressionJobs()
    def timeout = regressionTestTimeout()
    submitSlurmJob(
        'regression',
        'ci/jenkins/slurm-regression-tests.perlmutter-gpu.sh',
        '8',
        (env.PERLMUTTER_REGRESSION_TIME ?: '04:00:00').trim(),
        [
            "CI_BASELINE_DIR=${env.WORKSPACE}/_baseline",
            "CI_BASELINE_PREFIX=${env.WORKSPACE}/_baseline/gkylsoft",
            "CI_CANDIDATE_PREFIX=${env.WORKSPACE}/gkylsoft",
            "CI_REGRESSION_JOBS=${jobs}",
            "CI_REGRESSION_TEST_TIMEOUT=${timeout}"
        ]
    )
}

def configureAndCompileCRegressions(String label, String driver, String sourceDir, String prefix, String moduleFile) {
    withEnv([
        "CI_REGRESSION_LABEL=${label}",
        "CI_REGRESSION_DRIVER=${driver}",
        "CI_REGRESSION_SOURCE_DIR=${sourceDir}",
        "CI_REGRESSION_PREFIX=${prefix}",
        "CI_REGRESSION_MODULE_FILE=${moduleFile}"
    ]) {
        sh '''#!/bin/bash -l
            set -euo pipefail
            . "$CI_REGRESSION_MODULE_FILE"
            "$CI_REGRESSION_DRIVER" runregression configure \
                --source-dir "$CI_REGRESSION_SOURCE_DIR" \
                --prefix "$CI_REGRESSION_PREFIX"
            started="$(date +%s)"
            "$CI_REGRESSION_DRIVER" runregression run -c compile
            elapsed="$(( $(date +%s) - started ))"
            printf '%s\n' "$elapsed" > "$CI_REGRESSION_LABEL-c-compile-seconds.txt"
            echo "$CI_REGRESSION_LABEL C-regression compile time: $elapsed seconds"
        '''
    }
}

def finalizeUnfinishedSlurmJob() {
    // Jenkins may terminate a durable-task process tree before its shell trap
    // completes. Run this from the Pipeline finally block as a second chance
    // to cancel a submitted job and preserve an abort-status artifact.
    sh '''#!/bin/bash -l
        set -euo pipefail

        for id_file in slurm-*-job-id.txt; do
            [[ -e "$id_file" ]] || continue
            status_file="${id_file%-id.txt}-status.txt"
            [[ -e "$status_file" ]] && continue

            job_id="$(<"$id_file")"
            if [[ ! "$job_id" =~ ^[0-9]+(_[0-9]+)?$ ]]; then
                printf 'job_id=%s\nstate=UNKNOWN\nexit_code=\n' "$job_id" > "$status_file"
                echo "WARNING: Cannot cancel malformed Slurm job ID '$job_id'" >&2
                continue
            fi

            echo "Pipeline finalizer: cancelling unfinished Slurm job $job_id"
            scancel "$job_id" || true
            while :; do
                state="$(squeue --noheader --jobs="$job_id" --format='%T' | head -n 1 || true)"
                if [[ -z "$state" ]]; then
                    break
                fi
                echo "Pipeline finalizer: waiting for job $job_id to stop (state: $state)"
                sleep 5
            done
            printf 'job_id=%s\nstate=CANCELLED_BY_JENKINS\nexit_code=\n' "$job_id" > "$status_file"
        done
    '''
}

def writeCiTimingSummary() {
    sh '''#!/bin/bash -l
        set -euo pipefail

        metric() {
            local file="$1"
            local key="$2"
            if [[ -f "$file" ]]; then
                local value
                if [[ "$key" == '__file__' ]]; then
                    value="$(tr -d '[:space:]' < "$file")"
                else
                    value="$(sed -n -E "s/^${key}=//p" "$file" | tail -n 1)"
                fi
                if [[ -n "$value" ]]; then
                    printf '%s' "$value"
                    return
                fi
            fi
            printf 'not-recorded'
        }

        candidate_compile="$(metric candidate-c-compile-seconds.txt __file__)"
        baseline_compile="$(metric baseline-c-compile-seconds.txt __file__)"
        unit_elapsed="$(metric slurm-unit-job-status.txt elapsed_seconds)"
        regression_elapsed="$(metric slurm-regression-job-status.txt elapsed_seconds)"
        c_passed="$(metric ci-regression-summary.txt c_regression_passed)"
        c_acknowledged="$(metric ci-regression-summary.txt c_regression_acknowledged)"
        c_unacknowledged="$(metric ci-regression-summary.txt c_regression_unacknowledged)"

        compile_total='not-recorded'
        if [[ "$candidate_compile" =~ ^[0-9]+$ && "$baseline_compile" =~ ^[0-9]+$ ]]; then
            compile_total="$((candidate_compile + baseline_compile))"
        fi

        {
            printf 'candidate_c_compile_seconds=%s\n' "$candidate_compile"
            printf 'baseline_c_compile_seconds=%s\n' "$baseline_compile"
            printf 'login_c_compile_seconds=%s\n' "$compile_total"
            printf 'unit_slurm_elapsed_seconds=%s\n' "$unit_elapsed"
            printf 'regression_slurm_elapsed_seconds=%s\n' "$regression_elapsed"
            printf 'c_regression_passed=%s\n' "$c_passed"
            printf 'c_regression_acknowledged=%s\n' "$c_acknowledged"
            printf 'c_regression_unacknowledged=%s\n' "$c_unacknowledged"
        } > ci-timing-summary.txt
        cat ci-timing-summary.txt
    '''
}

def timingMetric(String key) {
    if (!fileExists('ci-timing-summary.txt')) {
        return 'n/a'
    }
    def expression = '(?m)^' + java.util.regex.Pattern.quote(key) + '=([^\\r\\n]+)$'
    def match = readFile('ci-timing-summary.txt') =~ expression
    return match.find() ? match.group(1) : 'n/a'
}

def timingStatusDescription(String status) {
    def passed = timingMetric('c_regression_passed')
    def acknowledged = timingMetric('c_regression_acknowledged')
    def unacknowledged = timingMetric('c_regression_unacknowledged')
    def candidateCompile = timingMetric('candidate_c_compile_seconds')
    def baselineCompile = timingMetric('baseline_c_compile_seconds')
    def unitElapsed = timingMetric('unit_slurm_elapsed_seconds')
    def regressionElapsed = timingMetric('regression_slurm_elapsed_seconds')
    def outcome = status == 'success' ? 'passed' : (status == 'error' ? 'errored' : 'failed')
    def description = "Perlmutter CI ${outcome}: C ${passed}/${acknowledged}/${unacknowledged}; comp C/B ${candidateCompile}/${baselineCompile}s; Slurm U/R ${unitElapsed}/${regressionElapsed}s"
    return description.take(140)
}

def candidatePr = params.CANDIDATE_PR?.trim()
def candidateRef = params.CANDIDATE_REF?.trim()
def requestedBaselineRef = params.BASELINE_REF?.trim()
if (!!candidatePr == !!candidateRef) {
    error('Set exactly one of CANDIDATE_PR or CANDIDATE_REF.')
}
if (candidatePr && !(candidatePr ==~ /[1-9][0-9]*/)) {
    error("CANDIDATE_PR must be a positive integer, got '${candidatePr}'.")
}
if (candidatePr && requestedBaselineRef) {
    error('BASELINE_REF must be empty with CANDIDATE_PR; the GitHub PR base branch is used automatically.')
}
if (candidateRef) {
    candidateRef = validateRefSelector('CANDIDATE_REF', candidateRef)
    requestedBaselineRef = validateRefSelector('BASELINE_REF', requestedBaselineRef)
}

def nodeLabel = (env.PERLMUTTER_INTEL_NODE_LABEL ?: 'perlmutter-gpu').trim()
def gkeyllCiRoot = requireValue('GKEYLL_CI_ROOT', env.GKEYLL_CI_ROOT)
def workspaceRoot = "${gkeyllCiRoot}/workspaces"
def credentialsId = requireValue('PERLMUTTER_GITHUB_CREDENTIAL_ID', env.PERLMUTTER_GITHUB_CREDENTIAL_ID)
def candidateSelector = ''
def baselineSelector = ''
def candidateCommit = ''
def terminalStatus = 'failure'
def terminalDescription = 'Perlmutter GPU CPU CI failed.'

node(nodeLabel) {
    // Perlmutter compute nodes must see this path. Configure the root on a shared
    // filesystem such as the project's /scratch/gpfs location, never /tmp.
    ws("${workspaceRoot}/${env.JOB_NAME}/${env.BUILD_TAG}") {
        try {
            stage('Resolve candidate and baseline') {
                if (candidatePr) {
                    candidateSelector = "PR #${candidatePr}"
                    baselineSelector = resolvePullRequestBase(credentialsId, candidatePr)
                } else {
                    candidateSelector = candidateRef
                    baselineSelector = requestedBaselineRef
                }
                echo "Candidate selector: ${candidateSelector}"
                echo "Baseline selector: ${baselineSelector}"
            }
            stage('Checkout candidate') {
                deleteDir()
                if (candidatePr) {
                    checkoutPullRequest(credentialsId, candidatePr)
                } else {
                    checkoutRef(credentialsId, candidateRef, 'candidate')
                }
                candidateCommit = sh(returnStdout: true, script: 'git rev-parse HEAD').trim()
                writeFile file: 'ci-candidate-commit.txt', text: "${candidateCommit}\n"
                writeFile file: 'ci-selection.txt', text: "candidate_selector=${candidateSelector}\nbaseline_selector=${baselineSelector}\n"
                sh 'git status --short'
            }
            stage('Report pending to GitHub') {
                publishGitHubCommitStatus(
                    credentialsId,
                    candidateCommit,
                    'pending',
                    'Perlmutter GPU candidate CI is running.'
                )
            }
            stage('Build dependencies') {
                withEnv(["PREFIX=${env.WORKSPACE}/gkylsoft"]) {
                    sh '''#!/bin/bash -l
                        set -euo pipefail
                        ./machines/mkdeps.perlmutter-gpu.sh
                    '''
                }
            }
            stage('Configure') {
                withEnv(["PREFIX=${env.WORKSPACE}/gkylsoft"]) {
                    sh '''#!/bin/bash -l
                        set -euo pipefail
                        ./machines/configure.perlmutter-gpu.sh
                    '''
                }
            }
            stage('Build unit tests') {
                def jobs = buildJobs()
                sh """#!/bin/bash -l
                    set -euo pipefail
                    # Each Jenkins sh step is a new process, so source the
                    # same environment used by the Perlmutter machine scripts.
                    . machines/module_load.perlmutter-gpu.sh
                    module list
                    make -j${jobs} unit
                """
            }
            stage('Run unit tests (SLURM)') {
                submitUnitTests()
            }
            stage('Install candidate for C regression') {
                def jobs = buildJobs()
                sh """#!/bin/bash -l
                    set -euo pipefail
                    . machines/module_load.perlmutter-gpu.sh
                    make -j${jobs} install
                """
            }
            stage('Compile candidate C regressions') {
                configureAndCompileCRegressions(
                    'candidate',
                    "${env.WORKSPACE}/gkylsoft/gkeyll/bin/gkeyll",
                    env.WORKSPACE,
                    "${env.WORKSPACE}/gkylsoft",
                    'machines/module_load.perlmutter-gpu.sh'
                )
            }
            stage('Checkout Perlmutter GPU baseline') {
                dir('_baseline') {
                    deleteDir()
                    checkoutRef(credentialsId, baselineSelector, 'baseline')
                    sh 'git rev-parse HEAD | tee ../ci-baseline-commit.txt'
                }
            }
            stage('Build Perlmutter GPU baseline') {
                withEnv(["PREFIX=${env.WORKSPACE}/_baseline/gkylsoft"]) {
                    dir('_baseline') {
                        sh '''#!/bin/bash -l
                            set -euo pipefail
                            . ../machines/module_load.perlmutter-gpu.sh
                            ./machines/mkdeps.perlmutter-gpu.sh
                            ./machines/configure.perlmutter-gpu.sh
                        '''
                    }
                }
            }
            stage('Install Perlmutter GPU baseline') {
                def jobs = buildJobs()
                dir('_baseline') {
                    sh """#!/bin/bash -l
                        set -euo pipefail
                        . ../machines/module_load.perlmutter-gpu.sh
                        make -j${jobs} install
                    """
                }
            }
            stage('Compile Perlmutter GPU baseline C regressions') {
                configureAndCompileCRegressions(
                    'baseline',
                    "${env.WORKSPACE}/_baseline/gkylsoft/gkeyll/bin/gkeyll",
                    "${env.WORKSPACE}/_baseline",
                    "${env.WORKSPACE}/_baseline/gkylsoft",
                    'machines/module_load.perlmutter-gpu.sh'
                )
            }
            stage('Run C regressions (SLURM)') {
                submitRegressionTests()
            }
            terminalStatus = 'success'
            terminalDescription = 'Perlmutter GPU CPU unit and C regression tests passed.'
        } catch (err) {
            if (currentBuild.currentResult == 'ABORTED' || err.toString().contains('FlowInterruptedException')) {
                terminalStatus = 'error'
                terminalDescription = 'Perlmutter GPU CPU CI was aborted.'
            }
            throw err
        } finally {
            try {
                finalizeUnfinishedSlurmJob()
            } catch (err) {
                terminalStatus = 'error'
                terminalDescription = 'Perlmutter GPU CPU CI cleanup failed.'
                throw err
            } finally {
                try {
                    writeCiTimingSummary()
                    terminalDescription = timingStatusDescription(terminalStatus)
                } catch (err) {
                    terminalStatus = 'error'
                    terminalDescription = 'Perlmutter GPU CPU CI timing summary failed.'
                    throw err
                }
                try {
                    archiveArtifacts allowEmptyArchive: true,
                        artifacts: 'ci-selection.txt,ci-candidate-commit.txt,ci-baseline-commit.txt,*-c-compile-seconds.txt,ci-timing-summary.txt,ci-regression-summary.txt,slurm-*.out,slurm-*-job-id.txt,slurm-*-job-status.txt,build/**/*.log,gkylsoft/gkeyll-results/**/regressiondb,gkylsoft/gkeyll-results/**/_rr_failures.txt,_baseline/gkylsoft/gkeyll-results/**/regressiondb,_baseline/gkylsoft/gkeyll-results/**/_rr_failures.txt'
                } catch (err) {
                    terminalStatus = 'error'
                    terminalDescription = 'Perlmutter GPU CPU CI artifact archival failed.'
                    throw err
                } finally {
                    try {
                        if (candidateCommit) {
                            publishGitHubCommitStatus(
                                credentialsId,
                                candidateCommit,
                                terminalStatus,
                                terminalDescription
                            )
                        }
                    } finally {
                        deleteDir()
                    }
                }
            }
        }
    }
}
README.perlmutter-gpu.md
# Manual Jenkins CI on Princeton Perlmutter GPU

This is the Level-1, CPU-only Gkeyll CI setup for NERSC's Perlmutter GPU
cluster. A person authenticates to Perlmutter with SSH/Duo, then manually starts
a Jenkins build for either a GitHub pull-request number or an explicitly
selected candidate branch/commit. Jenkins itself neither logs in through Duo
nor accepts GitHub webhooks.

The job runs `ci/jenkins/Jenkinsfile.perlmutter-gpu` from a reviewed, trusted
CI branch during bring-up. It fetches the requested `refs/pull/<number>/head`
commit, builds Gkeyll on the login node, then submits unit tests and all
supported C regression tests as separate CPU Slurm jobs. The C regressions use
a same-session `agent_tools-jenkins-perlmutter_gpu-baseline` baseline. Lua
regression, MPI, and GPU testing are deliberately not part of this setup.

## 0. Publish these CI files first

Create the dedicated branch `agent_tools-jenkins-perlmutter_gpu`, review, and
push the Perlmutter CI implementation files to it:

```text
ci/jenkins/Jenkinsfile.perlmutter-gpu
ci/jenkins/jenkins-perlmutter-gpu.sh
ci/jenkins/slurm-unit-tests.perlmutter-gpu.sh
ci/jenkins/slurm-regression-tests.perlmutter-gpu.sh
ci/jenkins/README.perlmutter-gpu.md
machines/module_load.perlmutter-gpu.sh
machines/mkdeps.perlmutter-gpu.sh
machines/configure.perlmutter-gpu.sh
```

Configure the initial Jenkins job to load its Pipeline script from this branch.
It is the trusted orchestration branch; do not point the job at an unreviewed
PR branch. After the pipeline has been validated and the change is merged,
switch its SCM branch specifier to `*/main`. No pipeline-code change is needed
at that point.

Create the fixed regression baseline from the same reviewed commit, then push
it. Keep this branch unchanged while candidate work is being compared against
it:

```sh
git branch agent_tools-jenkins-perlmutter_gpu-baseline HEAD
git push -u origin agent_tools-jenkins-perlmutter_gpu-baseline
```

## 1. Choose the CI root and Slurm settings

Keep the Jenkins controller, its installation, its workspaces, and all CI
artifacts under one shared, compute-node-visible directory:

```sh
export GKEYLL_CI_ROOT=/scratch/gpfs/$USER/gkeyll_ci
```

Perlmutter provides the username through `$USER`. The setup below creates:

```text
$GKEYLL_CI_ROOT/jenkins.war          Jenkins installation archive
$GKEYLL_CI_ROOT/jenkins_home/        JENKINS_HOME: controller configuration, plugins, jobs
$GKEYLL_CI_ROOT/jenkins_webroot/     unpacked Jenkins web application
$GKEYLL_CI_ROOT/tmp/                 controller temporary files
$GKEYLL_CI_ROOT/logs/                controller logs
$GKEYLL_CI_ROOT/workspaces/          Pipeline build workspaces and Slurm output
```

Do not use `/tmp`, `/home`, or a project directory for these CI files. The
pipeline creates an isolated workspace below `$GKEYLL_CI_ROOT/workspaces` for every
build. Since scratch storage can be purged, do not treat Jenkins build history
or credentials stored there as durable backups.

Record the Slurm values for your group:

```sh
qos
sshare
```

`PERLMUTTER_SLURM_QOS` is required. `PERLMUTTER_SLURM_ACCOUNT` is optional for PU
users but required for PPPL/CIMES users when their project policy requires
`--account`.

The initial job requests one task with four CPUs. `make unit-run` is launched
only once and does not distribute the full suite as a Slurm MPI job; the
four-CPU allocation is needed for its roughly 30 GB default memory allocation
(Perlmutter allocates 7.5 GB per core by default). In particular,
`test_dg_interpolate_3x2v_gk_ho` did not fit in a one-core allocation. Perlmutter
may place requests of 47 cores or fewer in its low-priority serial queue. Do
not request an entire 96-core node merely to bypass that queue; add a genuinely
parallel test profile first.

The separate C regression job requests one task with eight CPUs (roughly
60 GB by Perlmutter's 7.5 GB-per-core default) and runs four C cases at a time.
Its default four-hour allocation covers baseline creation and the PR check.
C executables are compiled before Slurm submission on the login node. Adjust
its settings only after measuring the complete first run.

## 2. Validate the cluster setup by hand

SSH to the Intel side and approve Duo:

```sh
ssh <NetID>@perlmutter.nersc.gov
```

Create a disposable checkout below the CI root. This branch contains the
Perlmutter pipeline files; do not use an unrelated checkout that might lack the
`machines/` configuration scripts or Slurm test payload.

```sh
export GKEYLL_CI_ROOT=/scratch/gpfs/$USER/gkeyll_ci
mkdir "$GKEYLL_CI_ROOT"
cd "$GKEYLL_CI_ROOT"
git clone --branch agent_tools-jenkins-perlmutter_gpu --single-branch \
  https://github.com/gkeyllorg/gkeyll.git gkeyll
cd gkeyll
```

From this `gkeyll/` checkout, validate the same environment the job will use:
`PREFIX="$PWD/../gkylsoft"` places the dependencies at
`$GKEYLL_CI_ROOT/gkylsoft`, beside the disposable source checkout.

```sh
PREFIX="$PWD/../gkylsoft" ./machines/mkdeps.perlmutter-gpu.sh
PREFIX="$PWD/../gkylsoft" ./machines/configure.perlmutter-gpu.sh
. ./machines/module_load.perlmutter-gpu.sh
make -j32 unit
make -j32 install
sbatch --wait --qos pppl-short --nodes 1 --ntasks 1 --cpus-per-task 4 \
  --time 00:30:00 --chdir "$PWD" \
  --export=ALL,CI_WORKSPACE="$PWD" \
  ci/jenkins/slurm-unit-tests.perlmutter-gpu.sh
```

For PPPL/CIMES, add `--account <your-account>` to the `sbatch` command. This
must complete successfully before introducing Jenkins. `CI_WORKSPACE` is the
shared checkout path that the batch payload uses after it starts on a compute
node; Jenkins supplies the same variable when it submits this job.

The machine configuration scripts run in child shells, so their environment
does not remain active for the later `make` command. Source
`machines/module_load.perlmutter-gpu.sh` before `make`; it is also sourced by the
machine scripts, Jenkins build stage, and Slurm payload. This keeps all
Perlmutter GPU module versions in one file.

### Validate the all-C regression comparison by hand

The regression job compares the current checkout with the fixed
`agent_tools-jenkins-perlmutter_gpu-baseline` baseline. Build and install that
baseline beside the candidate checkout, using its own dependency prefix:

```sh
cd "$GKEYLL_CI_ROOT"
git clone --branch agent_tools-jenkins-perlmutter_gpu-baseline --single-branch \
  https://github.com/gkeyllorg/gkeyll.git gkeyll-baseline
cd gkeyll-baseline
PREFIX="$PWD/gkylsoft" ./machines/mkdeps.perlmutter-gpu.sh
PREFIX="$PWD/gkylsoft" ./machines/configure.perlmutter-gpu.sh
. ../gkeyll/machines/module_load.perlmutter-gpu.sh
make -j32 install

"$PWD/gkylsoft/gkeyll/bin/gkeyll" runregression configure \
  --source-dir "$PWD" --prefix "$PWD/gkylsoft"
"$PWD/gkylsoft/gkeyll/bin/gkeyll" runregression run -c compile
```

Return to the candidate checkout, install it if the earlier unit-test
validation did not already do so, then configure and compile its C regressions
on the login node. This honors each layer's `ignore_c_tests.lua`:

```sh
cd "$GKEYLL_CI_ROOT/gkeyll"
. machines/module_load.perlmutter-gpu.sh
make -j32 install
"$PWD/gkylsoft/gkeyll/bin/gkeyll" runregression configure \
  --source-dir "$PWD" --prefix "$PWD/gkylsoft"
"$PWD/gkylsoft/gkeyll/bin/gkeyll" runregression run -c compile
```

Then submit the execution-only baseline/check workflow. It runs four C cases
concurrently and limits each case to 900 seconds:

```sh
cd "$GKEYLL_CI_ROOT/gkeyll"
sbatch --wait --qos pppl-short --nodes 1 --ntasks 1 --cpus-per-task 8 \
  --time 04:00:00 --chdir "$PWD" \
  --export=ALL,CI_WORKSPACE="$PWD",CI_BASELINE_DIR="$GKEYLL_CI_ROOT/gkeyll-baseline",CI_BASELINE_PREFIX="$GKEYLL_CI_ROOT/gkeyll-baseline/gkylsoft",CI_CANDIDATE_PREFIX="$GKEYLL_CI_ROOT/gkeyll/gkylsoft",CI_REGRESSION_JOBS=4,CI_REGRESSION_TEST_TIMEOUT=900 \
  ci/jenkins/slurm-regression-tests.perlmutter-gpu.sh
```

The baseline's `creg-accepted` output is moved into the candidate results tree and
is therefore disposable. Do not use a persistent accepted-output cache for
this workflow.

## 3. Install and run Jenkins privately

Perlmutter GPU is Red Hat Enterprise Linux 8.10. Because this is an
unprivileged personal setup, use the Jenkins WAR directly rather than a
system RPM/service. This procedure requires no root access: do not use
`sudo`, `dnf`, `rpm`, or `systemctl`. The login node's default Java is Java
17; current Jenkins requires Java 21 or later. Perlmutter's Java 21 location is
`/usr/lib/jvm/java-21-openjdk-21.0.12.1.1-1.1.el8.x86_64`. Do not use the
default `java` command unless `java -version` confirms it is Java 21 or newer.

After logging in through Duo, set up the scratch-only controller directory:

```sh
export GKEYLL_CI_ROOT=/scratch/gpfs/$USER/gkeyll_ci
export JAVA_HOME=/usr/lib/jvm/java-21-openjdk-21.0.12.1.1-1.1.el8.x86_64
export PATH="$JAVA_HOME/bin:$PATH"
export JENKINS_HOME="$GKEYLL_CI_ROOT/jenkins_home"
export JENKINS_WEBROOT="$GKEYLL_CI_ROOT/jenkins_webroot"
export TMPDIR="$GKEYLL_CI_ROOT/tmp"

mkdir -p "$JENKINS_HOME" "$JENKINS_WEBROOT" "$TMPDIR" \
  "$GKEYLL_CI_ROOT/logs" "$GKEYLL_CI_ROOT/workspaces"
java -version
```

The final command must report Java 21 or newer. Download the Jenkins LTS WAR
into the same directory; if Perlmutter cannot reach the download URL, download it
on the laptop and copy it into `$GKEYLL_CI_ROOT` through the authenticated SSH
connection instead:

```sh
cd "$GKEYLL_CI_ROOT"
curl -fL -o jenkins.war https://get.jenkins.io/war-stable/latest/jenkins.war
```

Start Jenkins in a named tmux session. This is the initial operational mode:
it keeps the controller available after SSH disconnects without installing a
system service. Stop it after a test session if it is not needed.

```sh
tmux new -s gkeyll_ci

export GKEYLL_CI_ROOT=/scratch/gpfs/$USER/gkeyll_ci
export JAVA_HOME=/usr/lib/jvm/java-21-openjdk-21.0.12.1.1-1.1.el8.x86_64
export PATH="$JAVA_HOME/bin:$PATH"
export JENKINS_HOME="$GKEYLL_CI_ROOT/jenkins_home"
export JENKINS_WEBROOT="$GKEYLL_CI_ROOT/jenkins_webroot"
export TMPDIR="$GKEYLL_CI_ROOT/tmp"

java -Djava.io.tmpdir="$TMPDIR" -jar "$GKEYLL_CI_ROOT/jenkins.war" \
  --webroot="$JENKINS_WEBROOT" \
  --httpListenAddress=127.0.0.1 \
  --httpPort=8080 \
  2>&1 | tee -a "$GKEYLL_CI_ROOT/logs/jenkins.log"
```

In another Perlmutter shell, use these commands to manage that controller:

```sh
tmux attach -t gkeyll_ci   # return to the Jenkins console
tmux ls                    # verify the session exists
tmux kill-session -t gkeyll_ci # stop Jenkins after testing
```

The controller must run as the same Unix account that owns the Slurm
allocation. It binds only to `127.0.0.1`; do not expose a public port or
configure a GitHub webhook for this Level-1 setup.

### Optional browser access

The command-line launcher below is the normal way to submit a build. The UI is
still available for one-time configuration, interactive inspection, or manual
**Build with Parameters** submissions. After SSH/Duo authentication from the
laptop, open a tunnel. The first port is
on the laptop and can be any unused port; the second is Jenkins' listening
port on Perlmutter. If Jenkins uses its default remote port 8080 and the Mac's
local Jenkins already owns local port 8080, use 8081 locally:

```sh
ssh -N -L 8081:127.0.0.1:8080 <NetID>@perlmutter.nersc.gov
```

Then open `http://localhost:8081` in the laptop browser. The Mac Jenkins
remains at `http://localhost:8080`; both interfaces can be open at once. If
you configure the Perlmutter Jenkins service itself to listen on a non-default
remote port, replace only the final `8080` in the tunnel command.

On its first start, get the unlock password with:

```sh
cat "$JENKINS_HOME/secrets/initialAdminPassword"
```

Complete Jenkins initial setup and create an administrator account.

Install these Jenkins plugins if they are not already present: Pipeline, Git,
Credentials Binding, and the Git client plugin. The Pipeline and Git plugins
are normally part of Jenkins' suggested-plugin installation.

### Create a Jenkins API token for the launcher

While signed in to the Jenkins UI as the user who will launch builds, create a
user API token in that user's security configuration. Store the Jenkins user
name and token in a file readable only by that Unix user:

```sh
umask 077
printf '%s:%s\n' '<jenkins-user>' '<jenkins-api-token>' \
  > "$JENKINS_HOME/jenkins-cli.auth"
chmod 600 "$JENKINS_HOME/jenkins-cli.auth"
```

This token is separate from the GitHub credential below. The launcher uses it
only against Jenkins at `127.0.0.1`; it neither changes browser login nor
disables Jenkins CSRF protection.

## 4. Create the GitHub credential

Create a GitHub fine-grained token restricted to the `gkeyllorg/gkeyll`
repository. Grant `Contents: Read`, `Pull requests: Read`, and `Commit
statuses: Read and write`. In Jenkins add it as a Username-with-password
credential, using the GitHub username and token, and give it an ID such as
`gkeyll-github-stellar`. The Pipeline uses this one credential both to fetch
the PR and to publish its commit status.

The token never receives repository-content write permission, and the
Pipeline binds it only for Git checkout and short, trusted GitHub API calls;
it is not present while a command from the PR checkout runs. Do not put Duo
secrets, a personal SSH key, or unrelated credentials in the Jenkins account.

## 5. Configure the Jenkins node and global environment

Use the controller's built-in node or a local agent. Give it the label
`perlmutter-gpu` (or select another label and set
`PERLMUTTER_INTEL_NODE_LABEL` below). The agent must run on the Perlmutter GPU
login side and as the same Unix account that can submit Slurm jobs.

In **Manage Jenkins → System → Global properties → Environment variables**,
set:

| Name | Required value |
| --- | --- |
| `GKEYLL_CI_ROOT` | Output of `printf '/scratch/gpfs/%s/gkeyll_ci' "$USER"`; paste the expanded result, not a literal `$USER` |
| `PERLMUTTER_GITHUB_CREDENTIAL_ID` | Jenkins credential ID, e.g. `gkeyll-github-stellar` |
| `PERLMUTTER_SLURM_QOS` | Your valid CPU QoS, e.g. `pppl-short` |
| `PERLMUTTER_SLURM_ACCOUNT` | Project account, if required; otherwise omit it |
| `PERLMUTTER_SLURM_TIME` | Optional time limit; defaults to `00:30:00` |
| `PERLMUTTER_BUILD_JOBS` | Optional login-node compile parallelism; defaults to `3` |
| `PERLMUTTER_REGRESSION_TIME` | Optional C-regression allocation limit; defaults to `04:00:00` |
| `PERLMUTTER_REGRESSION_JOBS` | Optional concurrent C test runs; defaults to `4` |
| `PERLMUTTER_REGRESSION_TEST_TIMEOUT` | Optional per-C-test limit in seconds; defaults to `900` |
| `PERLMUTTER_INTEL_NODE_LABEL` | Optional agent label; defaults to `perlmutter-gpu` |

Do not set a broad global `PATH` to an interactive shell configuration. The
pipeline explicitly initializes the Perlmutter modules for every build and Slurm
job. `GKEYLL_CI_ROOT` is the Pipeline's only root setting; it must exactly
match the value used to set `JENKINS_HOME` when the controller was launched.
The Pipeline derives its workspace root as `$GKEYLL_CI_ROOT/workspaces`; do
not define a separate workspace-root variable.

## 6. Create the one parameterized Pipeline job

Create **New Item → Pipeline** named `gkeyll-ci-perlmutter-gpu`.

Configure its pipeline definition as **Pipeline script from SCM**:

- SCM: Git
- Repository: `https://github.com/gkeyllorg/gkeyll.git`
- Credentials: the read-only GitHub credential
- Branch specifier: `*/agent_tools-jenkins-perlmutter_gpu`
- Script path: `ci/jenkins/Jenkinsfile.perlmutter-gpu`

The CI-branch selection is intentional during bring-up. Do not point this job
at a PR branch or let the requested PR select its own Jenkinsfile. Once this
pipeline is validated and merged, change this branch specifier to `*/main`.

Leave **This project is parameterized** unchecked. The trusted Pipeline file
declares and owns its three parameters; do not add them manually in the
Jenkins UI. On a newly created job, click **Build Now** once. That initial
build stops immediately because neither candidate selector is set, but it
registers the Pipeline-declared parameters with Jenkins. Thereafter Jenkins
displays **Build with Parameters**. The initial empty build is expected and
does not submit a Slurm job.

The selectors are:

| Parameter | Use |
| --- | --- |
| `CANDIDATE_PR` | A positive GitHub PR number. Leave both reference fields empty. Jenkins obtains the PR's current head commit and asks GitHub which base branch that PR targets; that base branch is the baseline. |
| `CANDIDATE_REF` | A candidate branch name or a full 40-character commit SHA. Set this instead of `CANDIDATE_PR`. |
| `BASELINE_REF` | A baseline branch name or full 40-character commit SHA. It is required with `CANDIDATE_REF`, and must be empty with `CANDIDATE_PR`. |

Tags are deliberately not accepted. This keeps a run's input unambiguous and
avoids testing an unexpectedly retargeted tag.

## 7. Run and inspect a build

### Single-session command-line launch

After SSH/Duo authentication, run the launcher from the reviewed CI checkout.
It defaults `GKEYLL_CI_ROOT` to `/scratch/gpfs/$USER/gkeyll_ci`, starts the
controller in a detached `gkeyll_ci` tmux session when necessary, and submits
the existing `gkeyll-ci-perlmutter-gpu` job through its loopback-only API:

```sh
# Queue a PR build and return after Jenkins accepts it.
ci/jenkins/jenkins-perlmutter-gpu.sh run --pr 1104

# Queue a direct-ref build and follow it through its final result.
ci/jenkins/jenkins-perlmutter-gpu.sh run \
  --candidate-ref feature/new-solver --baseline-ref main --follow
```

The default command prints a Jenkins queue ID and returns so the SSH terminal
is immediately available. `follow --queue` resolves a queue item that has
already started through the retained Jenkins build metadata; use the assigned
build number directly when it is known:

```sh
ci/jenkins/jenkins-perlmutter-gpu.sh follow --queue 42
ci/jenkins/jenkins-perlmutter-gpu.sh follow --build 187
ci/jenkins/jenkins-perlmutter-gpu.sh status --build 187

# Recover build and queue identifiers after reconnecting.
ci/jenkins/jenkins-perlmutter-gpu.sh active
ci/jenkins/jenkins-perlmutter-gpu.sh recent
ci/jenkins/jenkins-perlmutter-gpu.sh recent --limit 5
```

`active` lists queued and running builds for this Jenkins job. `recent` lists
the most recent 10 retained builds (or the requested positive `--limit`), with
their queue IDs, selectors, state, time, and Jenkins URL. Both commands include
builds submitted through the UI as well as the launcher.

`--follow` waits for Jenkins to assign the queue item a build number, streams
the Pipeline console (including Slurm state), prints its terminal result, and
returns zero only for `SUCCESS`. It does not move the controller or Pipeline
into the SSH shell: an SSH disconnect or interrupt stops only the local
monitor, while Jenkins in tmux and submitted Slurm jobs continue. Attach to
the controller console for diagnosis with `tmux attach -t gkeyll_ci`.
Press `Ctrl-C` while following to stop monitoring and return to the SSH shell;
it does not abort the Jenkins build.

Internally, the follow operation uses the controller-matched Jenkins CLI JAR
with an API-token credential file; this is useful for direct diagnosis but the
launcher should be used for ordinary runs:

```sh
java -jar "$GKEYLL_CI_ROOT/jenkins-cli.jar" \
  -s http://127.0.0.1:8080 \
  -http \
  -auth @"$JENKINS_HOME/jenkins-cli.auth" \
  console gkeyll-ci-perlmutter-gpu 187 -f
```

The UI remains a fully supported alternative. A UI-triggered build and a
launcher-triggered build submit the same job and parameters; the existing
`disableConcurrentBuilds()` setting makes the later request wait in Jenkins'
queue.

### Browser launch

After reaching Jenkins through the SSH tunnel, select **Build with
Parameters** and choose one selector form. For a PR run, set
`CANDIDATE_PR` (for example `1104`) and leave `CANDIDATE_REF` and
`BASELINE_REF` empty. For a branch or exact-commit run, set both
`CANDIDATE_REF` and `BASELINE_REF`. Jenkins records the requested selectors
and exact checked-out commits, immediately posts the GitHub commit status
`continuous-integration/jenkins/perlmutter-gpu` as pending, builds unit tests
and both installs on the login node, then submits separate unit and C
regression payloads to Slurm. The C job builds accepted outputs from the
selected baseline and compares all
non-ignored C regressions from the candidate against them. Both C suites are
compiled on the login node before
the regression allocation is submitted; the allocation executes only the
precompiled tests.

The final regression check uses the existing
`ci/jenkins/expected_regression_diffs.txt` acknowledgement policy. A real,
reviewed change in numerical output must be added there deliberately; an
unlisted regression difference fails the build and is reported in the Jenkins
console and result database.

The final GitHub-status description contains the candidate C
`passed/acknowledged/unacknowledged` counts, candidate/baseline C compilation
seconds, and unit/regression Slurm execution seconds. Missing metrics from an
early failure are shown as `not-recorded`. The full key/value record is always
printed to the console and archived as `ci-timing-summary.txt`.

At the end of the Pipeline, the same status becomes `success` for a passing
build, `failure` for a build/test/Slurm failure, or `error` for an aborted
build or controller-side cleanup problem. The status is attached to the exact
candidate commit. A PR run therefore appears on its PR; a direct-ref run
appears on that commit's GitHub commit page/history and will also appear in a
PR only if that exact commit later becomes its head. The Perlmutter Jenkins URL
is private behind SSH/Duo, so GitHub does not receive a build URL.

Failure to publish either the pending or final GitHub status fails the Jenkins
build. This prevents a green Jenkins result from silently lacking its GitHub
report.

While the Slurm job is pending or running, the Jenkins console prints its
state from `squeue`. Once it leaves the queue, Jenkins obtains its final state,
exit code, and `ElapsedRaw` execution time from `sacct`; only `COMPLETED` with
exit code `0:0` is a passing build. Queue time is not included in that elapsed
time. The archived artifacts include:

```text
ci-selection.txt                    requested candidate and baseline selectors
ci-candidate-commit.txt             exact tested candidate commit
ci-baseline-commit.txt              exact Perlmutter GPU baseline commit
candidate-c-compile-seconds.txt     candidate C-regression compile duration
baseline-c-compile-seconds.txt      baseline C-regression compile duration
ci-regression-summary.txt           candidate C pass/acknowledged/failure counts
ci-timing-summary.txt               aggregate compile and Slurm execution timings
slurm-unit-job-id.txt               submitted unit-job ID
slurm-unit-job-status.txt           unit-job terminal state, exit code, elapsed seconds
slurm-regression-job-id.txt         submitted regression-job ID
slurm-regression-job-status.txt     regression terminal state, exit code, elapsed seconds
slurm-unit-<jobid>.out              unit-job stdout/stderr
slurm-regression-<jobid>.out        regression-job stdout/stderr
`gkylsoft/gkeyll-results/**/regressiondb`  candidate C-regression results
```

To stop a queued or running build, use **Abort** in Jenkins. The submission
shell cancels its recorded Slurm job and waits until it disappears from
`squeue`. If Jenkins terminates that shell before its trap completes, the
Pipeline's finalizer performs the same cancellation and writes the relevant
`slurm-*-job-status.txt` before artifact archival. Do not manually remove the
workspace while the job appears in `squeue`.

If the Jenkins controller itself crashes, its shell trap cannot run. Find the
job ID in the build workspace or Jenkins console, then check and, if needed,
cancel it manually:

```sh
squeue --me
scancel <jobid>
```

After Slurm has stopped, it is safe to remove the abandoned workspace. Restart
Jenkins in the `gkeyll_ci` tmux session as described above; its job
configuration and retained build records live under `$JENKINS_HOME`.

The Pipeline archives artifacts before deleting every completed, failed, or
aborted build workspace. Jenkins retains the 20 most recent build records and
their artifacts; older records are discarded automatically.

## What this does not yet do

- automatic GitHub polling or webhooks;
- Lua regression, MPI regression, MOAT-only regression, or GPU tests;
- automatic recovery of a Slurm job after a Jenkins-controller crash.

Those are future stages, after this manually-triggered CPU unit-and-C-
regression path is reliable.
jenkins-perlmutter-gpu.sh
#!/usr/bin/env bash
#
# Start and use the private, loopback-only Jenkins controller on Perlmutter GPU.
# This is intentionally a controller launcher, not a replacement for the
# Jenkins UI: both clients submit the same parameterized Pipeline job.

set -euo pipefail

readonly SCRIPT_PATH="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/$(basename -- "${BASH_SOURCE[0]}")"
readonly DEFAULT_JAVA_HOME=/usr/lib/jvm/java-21-openjdk-21.0.12.1.1-1.1.el8.x86_64

CI_ROOT="${GKEYLL_CI_ROOT:-/scratch/gpfs/${USER:?USER must be set}/gkeyll_ci}"
JENKINS_HOME="${JENKINS_HOME:-$CI_ROOT/jenkins_home}"
JENKINS_WEBROOT="${JENKINS_WEBROOT:-$CI_ROOT/jenkins_webroot}"
JENKINS_TMPDIR="${TMPDIR:-$CI_ROOT/tmp}"
JENKINS_PORT="${JENKINS_PORT:-8080}"
JENKINS_URL="${JENKINS_URL:-http://127.0.0.1:$JENKINS_PORT}"
JENKINS_JOB="${JENKINS_JOB:-gkeyll-ci-perlmutter-gpu}"
JENKINS_SESSION="${JENKINS_SESSION:-gkeyll_ci}"
JENKINS_CLI_AUTH_FILE="${JENKINS_CLI_AUTH_FILE:-$JENKINS_HOME/jenkins-cli.auth}"
JAVA_HOME="${JAVA_HOME:-$DEFAULT_JAVA_HOME}"
CLI_JAR="$CI_ROOT/jenkins-cli.jar"

CURL_CONFIG=''
SUBMITTED_QUEUE_ID=''
RESOLVED_BUILD_NUMBER=''

die() {
    echo "ERROR: $*" >&2
    exit 1
}

usage() {
    cat <<'EOF'
Usage:
  jenkins-perlmutter-gpu.sh <command> [flags]

Commands:
  start                                      Start Jenkins in detached tmux.
  run --pr NUMBER [--follow]                 Queue a GitHub pull-request build.
  run --candidate-ref REF --baseline-ref REF [--follow]
                                             Queue a branch or commit comparison.
  follow --queue ID                          Wait for and stream a queued build.
  follow --build NUMBER                      Stream a known Jenkins build.
  status --queue ID                          Show a queued build's current state.
  status --build NUMBER                      Show a known build's current state.
  active                                     List this job's queued and running work.
  recent [--limit NUMBER]                    List retained builds (default: 10).

The run command returns after Jenkins accepts the request. --follow streams
the build console and returns its final Jenkins result. Press Ctrl-C to stop
following without aborting the Jenkins build.

GKEYLL_CI_ROOT defaults to /scratch/gpfs/$USER/gkeyll_ci. The Jenkins API
credential file defaults to $JENKINS_HOME/jenkins-cli.auth and must contain
one line in the form: jenkins-user:api-token
EOF
}

prepare_paths() {
    mkdir -p "$JENKINS_HOME" "$JENKINS_WEBROOT" "$JENKINS_TMPDIR" \
        "$CI_ROOT/logs" "$CI_ROOT/workspaces"
}

controller_running() {
    tmux has-session -t "$JENKINS_SESSION" 2>/dev/null
}

wait_for_controller() {
    local attempt
    for attempt in {1..30}; do
        if curl --fail --silent --show-error --max-time 5 \
            --output /dev/null "$JENKINS_URL/login"; then
            return 0
        fi
        sleep 2
    done
    die "Jenkins did not become ready at $JENKINS_URL. Inspect: tmux attach -t $JENKINS_SESSION"
}

start_controller() {
    prepare_paths
    [[ -x "$JAVA_HOME/bin/java" ]] || die "Java 21 was not found at $JAVA_HOME/bin/java"
    [[ -f "$CI_ROOT/jenkins.war" ]] || die "Jenkins WAR is missing: $CI_ROOT/jenkins.war"

    if controller_running; then
        echo "Jenkins tmux session already exists: $JENKINS_SESSION"
    else
        tmux new-session -d -s "$JENKINS_SESSION" "$SCRIPT_PATH" __controller
        echo "Started Jenkins in tmux session: $JENKINS_SESSION"
    fi
    wait_for_controller
    echo "Jenkins is ready at $JENKINS_URL"
}

run_controller() {
    prepare_paths
    [[ -x "$JAVA_HOME/bin/java" ]] || die "Java 21 was not found at $JAVA_HOME/bin/java"
    [[ -f "$CI_ROOT/jenkins.war" ]] || die "Jenkins WAR is missing: $CI_ROOT/jenkins.war"

    export JENKINS_HOME JENKINS_WEBROOT
    export TMPDIR="$JENKINS_TMPDIR"
    export PATH="$JAVA_HOME/bin:$PATH"
    "$JAVA_HOME/bin/java" -Djava.io.tmpdir="$TMPDIR" -jar "$CI_ROOT/jenkins.war" \
        --webroot="$JENKINS_WEBROOT" \
        --httpListenAddress=127.0.0.1 \
        --httpPort="$JENKINS_PORT" \
        2>&1 | tee -a "$CI_ROOT/logs/jenkins.log"
}

cleanup_curl_config() {
    if [[ -n "$CURL_CONFIG" ]]; then
        rm -f "$CURL_CONFIG"
    fi
}

prepare_auth() {
    [[ -f "$JENKINS_CLI_AUTH_FILE" ]] || die "Jenkins API credential file is missing: $JENKINS_CLI_AUTH_FILE"
    [[ -O "$JENKINS_CLI_AUTH_FILE" ]] || die "Jenkins API credential file is not owned by $USER: $JENKINS_CLI_AUTH_FILE"

    local mode credential
    mode="$(stat -c '%a' "$JENKINS_CLI_AUTH_FILE")"
    [[ "$mode" == 600 ]] || die "Jenkins API credential file must have mode 600: $JENKINS_CLI_AUTH_FILE"
    credential="$(<"$JENKINS_CLI_AUTH_FILE")"
    [[ "$credential" =~ ^[^[:space:]:]+:[^[:space:]:]+$ ]] || die "Jenkins API credential file must contain exactly user:api-token"
    [[ "$credential" != *'"'* && "$credential" != *'\\'* ]] || die "Jenkins API credential file contains an unsupported character"

    CURL_CONFIG="$(mktemp "$JENKINS_TMPDIR/jenkins-curl.XXXXXX")"
    chmod 600 "$CURL_CONFIG"
    printf 'user = "%s"\n' "$credential" > "$CURL_CONFIG"
    trap cleanup_curl_config EXIT
}

curl_auth() {
    curl --fail --silent --show-error --globoff --config "$CURL_CONFIG" "$@"
}

curl_auth_quiet() {
    curl --fail --silent --globoff --config "$CURL_CONFIG" "$@"
}

download_cli() {
    if [[ ! -s "$CLI_JAR" ]]; then
        local temporary_jar
        temporary_jar="$(mktemp "$JENKINS_TMPDIR/jenkins-cli.XXXXXX")"
        curl --fail --silent --show-error --output "$temporary_jar" \
            "$JENKINS_URL/jnlpJars/jenkins-cli.jar"
        mv "$temporary_jar" "$CLI_JAR"
    fi
}

require_positive_integer() {
    local name="$1" value="$2"
    [[ "$value" =~ ^[1-9][0-9]*$ ]] || die "$name must be a positive integer, got '$value'"
}

queue_state() {
    local queue_id="$1" payload
    # Jenkins discards a queue item after assigning its build. That expected
    # transition is handled by build_for_queue below, so do not print curl's
    # 404 before attempting the recovery path.
    payload="$(curl_auth_quiet "$JENKINS_URL/queue/item/$queue_id/api/json")" || return 1
    python3 -c '
import json
import sys
item = json.load(sys.stdin)
executable = item.get("executable") or {}
number = executable.get("number", "")
cancelled = "true" if item.get("cancelled", False) else "false"
why = " ".join((item.get("why") or "").split())
print(f"{number}\t{cancelled}\t{why}")
' <<< "$payload"
}

build_for_queue() {
    local queue_id="$1" payload
    payload="$(curl_auth "$JENKINS_URL/job/$JENKINS_JOB/api/json?tree=builds[number,queueId]")" || return 1
    python3 -c '
import json
import sys

queue_id = int(sys.argv[1])
for build in json.load(sys.stdin).get("builds", []):
    if build.get("queueId") == queue_id:
        print(build["number"])
        break
' "$queue_id" <<< "$payload"
}

build_state() {
    local build_number="$1" payload
    payload="$(curl_auth "$JENKINS_URL/job/$JENKINS_JOB/$build_number/api/json")" || return 1
    python3 -c '
import json
import sys
build = json.load(sys.stdin)
print("true" if build.get("building", False) else "false")
print(build.get("result") or "")
' <<< "$payload"
}

job_builds() {
    curl_auth "$JENKINS_URL/job/$JENKINS_JOB/api/json?tree=builds[number,queueId,building,result,timestamp,url,actions[parameters[name,value]]]"
}

queue_items() {
    curl_auth "$JENKINS_URL/queue/api/json?tree=items[id,task[name],why,cancelled,executable[number],actions[parameters[name,value]]]"
}

format_builds() {
    local limit="$1" active_only="$2" payload="$3"
    python3 -c '
import datetime
import json
import sys

limit = int(sys.argv[1])
active_only = sys.argv[2] == "true"

def selectors(actions):
    values = {}
    for action in actions or []:
        for parameter in action.get("parameters") or []:
            name = parameter.get("name")
            if name in ("CANDIDATE_PR", "CANDIDATE_REF", "BASELINE_REF"):
                values[name] = parameter.get("value") or "-"
    return "pr={0} candidate={1} baseline={2}".format(
        values.get("CANDIDATE_PR", "-"),
        values.get("CANDIDATE_REF", "-"),
        values.get("BASELINE_REF", "-"))

count = 0
for build in json.load(sys.stdin).get("builds", []):
    if active_only and not build.get("building", False):
        continue
    if count >= limit:
        break
    state = "RUNNING" if build.get("building", False) else (build.get("result") or "UNKNOWN")
    timestamp = build.get("timestamp")
    when = "-"
    if timestamp is not None:
        when = datetime.datetime.fromtimestamp(
            timestamp / 1000.0, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    queue_id = build.get("queueId")
    print("BUILD #{number} {state} queue={queue} {when} {selectors} url={url}".format(
        number=build.get("number", "?"), state=state, queue=queue_id if queue_id is not None else "-",
        when=when, selectors=selectors(build.get("actions")), url=build.get("url", "-")))
    count += 1
' "$limit" "$active_only" <<< "$payload"
}

format_queue_items() {
    local payload="$1"
    python3 -c '
import json
import sys

job = sys.argv[1]

def selectors(actions):
    values = {}
    for action in actions or []:
        for parameter in action.get("parameters") or []:
            name = parameter.get("name")
            if name in ("CANDIDATE_PR", "CANDIDATE_REF", "BASELINE_REF"):
                values[name] = parameter.get("value") or "-"
    return "pr={0} candidate={1} baseline={2}".format(
        values.get("CANDIDATE_PR", "-"),
        values.get("CANDIDATE_REF", "-"),
        values.get("BASELINE_REF", "-"))

for item in json.load(sys.stdin).get("items", []):
    if (item.get("task") or {}).get("name") != job:
        continue
    # A started item is displayed as its running build, not twice.
    if item.get("executable"):
        continue
    state = "CANCELLED" if item.get("cancelled", False) else "QUEUED"
    why = " ".join((item.get("why") or "waiting").split())
    print("QUEUE {id} {state} reason={why} {selectors}".format(
        id=item.get("id", "?"), state=state, why=why,
        selectors=selectors(item.get("actions"))))
' "$JENKINS_JOB" <<< "$payload"
}

wait_for_build_number() {
    local queue_id="$1" state number cancelled why previous='' attempt
    while :; do
        if ! state="$(queue_state "$queue_id")"; then
            # Jenkins normally removes a queue item as soon as it starts its
            # build. Build records retain queueId, so recover the assignment
            # from the job rather than requiring the caller to discover it.
            for attempt in {1..6}; do
                if number="$(build_for_queue "$queue_id")" && [[ -n "$number" ]]; then
                    RESOLVED_BUILD_NUMBER="$number"
                    return 0
                fi
                sleep 2
            done
            die "Queue item $queue_id is unavailable and no matching Jenkins build was found"
        fi
        IFS=$'\t' read -r number cancelled why <<< "$state"
        [[ "$cancelled" == false ]] || die "Queue item $queue_id was cancelled"
        if [[ -n "$number" ]]; then
            RESOLVED_BUILD_NUMBER="$number"
            return 0
        fi
        if [[ "$why" != "$previous" ]]; then
            echo "Queue item $queue_id: ${why:-waiting}" >&2
            previous="$why"
        fi
        sleep 5
    done
}

follow_build() {
    local build_number="$1" state building result
    require_positive_integer 'build number' "$build_number"
    download_cli
    echo "Following $JENKINS_JOB #$build_number"
    echo "Build URL: $JENKINS_URL/job/$JENKINS_JOB/$build_number/"

    # The CLI is only a console client. Let an interactive interrupt detach
    # this client cleanly; Jenkins in tmux and any Slurm jobs keep running.
    trap "echo 'Stopped following build #${build_number}'; exit 130" INT TERM HUP

    # -f follows console output without propagating a client interruption to
    # the Jenkins build. The controller and Slurm work remain independent of
    # the SSH terminal.
    if ! "$JAVA_HOME/bin/java" -jar "$CLI_JAR" -s "$JENKINS_URL" -http \
        -auth "@$JENKINS_CLI_AUTH_FILE" console "$JENKINS_JOB" "$build_number" -f; then
        echo "Console follower ended before Jenkins reported a terminal result; checking build status." >&2
    fi

    trap - INT TERM HUP

    while :; do
        mapfile -t state < <(build_state "$build_number")
        building="${state[0]:-}"
        result="${state[1]:-}"
        [[ "$building" == false ]] && break
        sleep 5
    done

    echo "Build #$build_number result: ${result:-UNKNOWN}"
    [[ "$result" == SUCCESS ]]
}

submit_build() {
    local candidate_pr="$1" candidate_ref="$2" baseline_ref="$3"
    local headers queue_url queue_id
    headers="$(mktemp "$JENKINS_TMPDIR/jenkins-headers.XXXXXX")"

    if ! curl_auth --dump-header "$headers" --output /dev/null --request POST \
        --data-urlencode "CANDIDATE_PR=$candidate_pr" \
        --data-urlencode "CANDIDATE_REF=$candidate_ref" \
        --data-urlencode "BASELINE_REF=$baseline_ref" \
        "$JENKINS_URL/job/$JENKINS_JOB/buildWithParameters"; then
        rm -f "$headers"
        die 'Jenkins rejected the build submission'
    fi
    queue_url="$(awk 'BEGIN { IGNORECASE=1 } /^Location:/ { sub(/^[^:]*:[[:space:]]*/, ""); sub(/\r$/, ""); print; exit }' "$headers")"
    rm -f "$headers"
    [[ "$queue_url" =~ /queue/item/([0-9]+)/ ]] || die "Jenkins accepted the request but did not return a queue location"
    queue_id="${BASH_REMATCH[1]}"

    echo "Queued $JENKINS_JOB as queue item $queue_id" >&2
    echo "Queue URL: $queue_url" >&2
    echo "Monitor it with: $SCRIPT_PATH follow --queue $queue_id" >&2
    SUBMITTED_QUEUE_ID="$queue_id"
}

run_command() {
    local candidate_pr='' candidate_ref='' baseline_ref='' follow=false queue_id
    while (($#)); do
        case "$1" in
            --pr)
                (($# >= 2)) || die '--pr requires a number'
                candidate_pr="$2"
                shift 2
                ;;
            --candidate-ref)
                (($# >= 2)) || die '--candidate-ref requires a ref'
                candidate_ref="$2"
                shift 2
                ;;
            --baseline-ref)
                (($# >= 2)) || die '--baseline-ref requires a ref'
                baseline_ref="$2"
                shift 2
                ;;
            --follow)
                follow=true
                shift
                ;;
            *) die "unknown run option: $1" ;;
        esac
    done

    if [[ -n "$candidate_pr" ]]; then
        require_positive_integer '--pr' "$candidate_pr"
        [[ -z "$candidate_ref$baseline_ref" ]] || die '--pr cannot be combined with candidate/baseline refs'
    else
        [[ -n "$candidate_ref" && -n "$baseline_ref" ]] || die 'provide --pr, or both --candidate-ref and --baseline-ref'
    fi

    start_controller
    prepare_auth
    submit_build "$candidate_pr" "$candidate_ref" "$baseline_ref"
    queue_id="$SUBMITTED_QUEUE_ID"
    if [[ "$follow" == true ]]; then
        local build_number
        wait_for_build_number "$queue_id"
        build_number="$RESOLVED_BUILD_NUMBER"
        follow_build "$build_number"
    fi
}

follow_command() {
    [[ $# -eq 2 ]] || die 'usage: follow --queue ID | follow --build NUMBER'
    start_controller
    prepare_auth
    case "$1" in
        --queue)
            require_positive_integer 'queue ID' "$2"
            wait_for_build_number "$2"
            follow_build "$RESOLVED_BUILD_NUMBER"
            ;;
        --build)
            follow_build "$2"
            ;;
        *) die 'usage: follow --queue ID | follow --build NUMBER' ;;
    esac
}

status_command() {
    [[ $# -eq 2 ]] || die 'usage: status --queue ID | status --build NUMBER'
    start_controller
    prepare_auth
    case "$1" in
        --queue)
            require_positive_integer 'queue ID' "$2"
            local state number cancelled why
            state="$(queue_state "$2")" || die "Queue item $2 is unavailable"
            IFS=$'\t' read -r number cancelled why <<< "$state"
            if [[ -n "$number" ]]; then
                echo "Queue item $2 is build #$number"
                status_command --build "$number"
            elif [[ "$cancelled" == true ]]; then
                echo "Queue item $2: CANCELLED"
                return 1
            else
                echo "Queue item $2: ${why:-waiting}"
            fi
            ;;
        --build)
            require_positive_integer 'build number' "$2"
            local build
            mapfile -t build < <(build_state "$2")
            if [[ "${build[0]:-}" == true ]]; then
                echo "Build #$2: BUILDING"
            else
                echo "Build #$2: ${build[1]:-UNKNOWN}"
                [[ "${build[1]:-}" == SUCCESS ]]
            fi
            ;;
        *) die 'usage: status --queue ID | status --build NUMBER' ;;
    esac
}

active_command() {
    local builds queues output
    [[ $# -eq 0 ]] || die 'usage: active'
    start_controller
    prepare_auth
    builds="$(job_builds)"
    queues="$(queue_items)"
    output="$(format_builds 100 true "$builds")"
    output+=$'\n'"$(format_queue_items "$queues")"
    if [[ -z "${output//$'\n'/}" ]]; then
        echo "No queued or running builds for $JENKINS_JOB"
    else
        printf '%s\n' "$output"
    fi
}

recent_command() {
    local limit=10 builds output
    if [[ $# -gt 0 ]]; then
        [[ $# -eq 2 && "$1" == --limit ]] || die 'usage: recent [--limit NUMBER]'
        limit="$2"
    fi
    require_positive_integer '--limit' "$limit"
    start_controller
    prepare_auth
    builds="$(job_builds)"
    output="$(format_builds "$limit" false "$builds")"
    if [[ -z "$output" ]]; then
        echo "No retained builds for $JENKINS_JOB"
    else
        printf '%s\n' "$output"
    fi
}

main() {
    (($# >= 1)) || { usage; exit 2; }
    case "$1" in
        __controller) shift; (($# == 0)) || die '__controller takes no arguments'; run_controller ;;
        start) shift; (($# == 0)) || die 'start takes no arguments'; start_controller ;;
        run) shift; run_command "$@" ;;
        follow) shift; follow_command "$@" ;;
        status) shift; status_command "$@" ;;
        active) shift; active_command "$@" ;;
        recent) shift; recent_command "$@" ;;
        -h|--help|help) usage ;;
        *) usage >&2; die "unknown command: $1" ;;
    esac
}

main "$@"
